-- Offline additions to voice-configuration-recovery-foundation.sql.
alter table public.icash_accounts add owner_user_id uuid;
alter table public.icash_voice_contact_targets add phone text default '+12025550101';
alter table public.icash_call_recordings add account_id uuid,add screening_id uuid,add from_phone text,add to_phone text;
create table public.icash_deal_files(id uuid primary key,account_id uuid,screening_id uuid);
create table public.icash_text_senders(phone text primary key,enabled boolean);
create table public.icash_business_voice_numbers(phone text primary key,outbound_enabled boolean,forwarding_ready boolean,caller_id_sid text);
create table public.icash_text_threads(id uuid primary key default gen_random_uuid(),account_id uuid,deal_id uuid,sender text,recipient text,party text,retired_at timestamptz);
create view public.icash_non_test_text_threads as select * from public.icash_text_threads;
create table public.icash_customer_phone_calls(account_id uuid,screening_id uuid,business_phone text,recipient_phone text);
create table public.icash_sms_routes(sender text,recipient text,account_id uuid,needs_review boolean);
create table public.icash_text_suppressions(phone text);
create table public.icash_webinar_phone_suppressions(phone text);
create table public.icash_contact_suppressions(contact_key text);
create table public.fixture_role_conflicts(sender text,recipient text);
create function public.icash_text_role_conflict(text,text) returns boolean language sql stable as $$select exists(select 1 from public.fixture_role_conflicts where sender=$1 and recipient=$2)$$;
create table public.icash_seller_intakes(id uuid,assigned_account uuid,screening_id uuid,request_id uuid,phone text,state text,ai_consented boolean,contact_consent_scope text,attribution jsonb);
create table public.icash_seller_matches(lead_id uuid,account_id uuid,screening_id uuid);
create table public.icash_optin_call_requests(lead_id uuid,request_id uuid,phone text,source text,account_id uuid,requested_by uuid,request_version text,request_reference text);
create schema icash_text_receipt_private;
create table public.fixture_delayed_senders(phone text);
create table public.icash_operational_contacts(account_id uuid,screening_id uuid,channel text,phone text,eligibility_until timestamptz,revoked_at timestamptz);
insert into public.fixture_policy values('sms_channel',true);
create function public.icash_outreach_sms_current(uuid) returns boolean language sql stable as $$select allowed from public.fixture_policy where kind='sms_channel'$$;
create function icash_text_receipt_private.sender_opener_available(text) returns boolean language sql stable as $$select not exists(select 1 from public.fixture_delayed_senders where phone=$1)$$;
create function icash_recording_private.voice_capacity_snapshot() returns jsonb language sql as $$select '{}'::jsonb$$;
create function icash_recording_private.voice_capacity_from_snapshot(uuid,text,text,text,boolean,jsonb) returns boolean language sql as $$select public.icash_voice_capacity_available($1,$2,$3,$4,$5)$$;
create function icash_recording_private.voice_queue_slot_from_snapshot(uuid,uuid,jsonb) returns boolean language sql as $$select public.icash_voice_queue_slot_open($1,$2)$$;
create function public.icash_property_call_sender(uuid,uuid,text) returns text language sql stable as $$select public.icash_business_conversation_sender($1,$2,$3,true)$$;
